/* @lc app=leetcode id=3900 lang=kotlin */ class Solution { fun fi(a: List<Int>, v: Int): Int = generateSequence(0 to a.size) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { m -> if (a[m] < v) m + 1 to hi else lo to m } }.last().first fun fz(a: IntArray, c: Int): Int = generateSequence(0 to a.size) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { m -> if (a[m] <= c) m + 1 to hi else lo to m } }.last().first fun longestBalanced(s: String): Int = s.length.let { n -> s.runningFold(0) { p, c -> p + if (c == '1') 1 else -1 }.let { P -> s.runningFold(0) { z, c -> z + if (c == '0') 1 else 0 }.toIntArray().let { Zp -> IntArray(n + 1) { it - Zp[it] }.let { Op -> (0..n).groupBy { P[it] }.let { pos -> (Zp[n]).let { Z -> (n - Z).let { T -> (1..n).maxOf { j -> maxOf(j - pos[P[j]]!!.first(), pos[P[j] - 2]?.let { l -> fi(l, fz(Zp, Zp[j] - Z)).let { ix -> if (ix < l.size && l[ix] < j) j - l[ix] else 0 } } ?: 0, pos[P[j] + 2]?.let { l -> fi(l, fz(Op, Op[j] - T)).let { ix -> if (ix < l.size && l[ix] < j) j - l[ix] else 0 } } ?: 0) } } } } } } } } }